INSERT INTO don_vi_tri_thuc (id, ma, tieu_de, loai, khai_niem_id, truong_phai_id, gia_tri_kich_hoat, dieu_kien_json, noi_dung, cau_hoi, nguon_id, chuong, trang_tu, trang_den, muc_tin_cay, nhan_su_dung, ly_do_nhan, phien_ban, trang_thai, nguoi_tao, nguoi_duyet, ghi_chu) VALUES
(316, 'VED-JOH-TAM-HON-1', 'Số tâm hồn 1 — Hành tinh Mặt Trời (Surya) (Johari)', 'QUY_TAC', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Theo Harish Johari (§4, tr.PDF 16–18), Số tâm hồn 1 (chủ quản bởi Mặt Trời) mang lại phong thái tự chủ, kỷ luật, giàu ý chí lãnh đạo, thẳng thắn và luôn muốn tự định đoạt hướng đi.', 'AI', 4, '§4', 16, 18, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(317, 'VED-JOH-DINH-MENH-1', 'Số định mệnh 1 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '1', '{"chi_so": "JOHARI_DINH_MENH", "bang": 1}', 'Theo Johari (§4, tr.PDF 19–20), Số định mệnh 1 là con số thuận lợi cho sự nghiệp lãnh đạo: sau tuổi 35, bạn có xu hướng đạt được vị thế độc lập, uy tín xã hội và sự công nhận nhờ nỗ lực bền bỉ.', 'AI', 4, '§4', 19, 20, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(318, 'VED-JOH-KHUYEN-CAO-NGHE-1', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 1 (Johari)', 'QUY_TAC', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Johari (§4, tr.PDF 18, 20) khuyên bạn tránh tính độc đoán, nóng nảy hoặc đòi hỏi sự tôn trọng quá mức; nên học cách khiêm tốn lắng nghe. Nghề nghiệp phù hợp là quản lý hành chính, lãnh đạo tổ chức, chính trị, y khoa và điều hành doanh nghiệp.', 'DI_THE_NAO', 4, '§4', 18, 20, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(319, 'VED-JOH-NGHE-DINH-MENH-1', 'Định hướng nghề nghiệp theo Số định mệnh 1 (Johari)', 'QUY_TAC', 21, 2, '1', '{"chi_so": "JOHARI_DINH_MENH", "bang": 1}', 'Theo Johari (§4, tr.PDF 19), với Số định mệnh 1 (Mặt Trời (Surya)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: quản lý hành chính, lãnh đạo tổ chức, chính trị, y khoa và điều hành doanh nghiệp.', 'DI_THE_NAO', 4, '§4', 19, 21, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(320, 'VED-JOH-THOI-DIEM-1', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 1 (Johari)', 'QUY_TAC', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Theo Johari (§4, tr.PDF 24), giai đoạn tuổi phát triển mạnh mẽ nhất của năng lượng số 1 là từ 35 đến 49 tuổi; khoảng thời gian vượng năng lượng trong năm là từ 21/3 đến 28/4 và từ 10/7 đến 20/8.', 'GAP_GI', 4, '§4', 24, 25, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(321, 'VED-JOH-VAN-HOA-1', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 1 (Johari)', 'QUY_TAC', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Theo Johari (§4, tr.PDF 23–24), gợi ý văn hoá Vệ Đà cho số 1: màu sắc hài hoà là vàng cam, vàng đồng, đỏ nhạt; ngày trong tuần thuận lợi là Chủ nhật và Thứ Hai; các ngày hợp trong tháng là 1, 10, 19, 28.', 'DI_THE_NAO', 4, '§4', 23, 25, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(322, 'VED-JOH-QUAN-HE-1', 'Quan hệ tương hợp / đối nghịch của Số 1 (Johari)', 'QUY_TAC', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Theo Johari (§4, tr.PDF 21–22), số 1 tương hợp với các số 1, 2, 3, 5, 6, 9; trung tính với 4, 7; và có độ căng (đối nghịch) với số 8.', 'DI_THE_NAO', 4, '§4', 21, 22, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(323, 'VED-JOH-DA-QUY-NHIN-AN-1', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 1 (Johari)', 'MO_TA', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Theo Johari (§4, tr.PDF 22–24), đá quý truyền thống gắn với số 1 là hồng ngọc (Ruby), thần chú Mặt Trời và nghi thức nhịn ăn ngày Chủ nhật.', 'DI_THE_NAO', 4, '§4', 22, 24, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(324, 'VED-JOH-AYURVEDA-BENH-1', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 1 (Johari)', 'MO_TA', 20, 2, '1', '{"chi_so": "JOHARI_TAM_HON", "bang": 1}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 1 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§4).', 'NEN_TANG', 4, '§4', 20, 21, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(325, 'VED-JOH-TAM-HON-2', 'Số tâm hồn 2 — Hành tinh Mặt Trăng (Chandra) (Johari)', 'QUY_TAC', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Theo Harish Johari (§5, tr.PDF 26–28), Số tâm hồn 2 (chủ quản bởi Mặt Trăng) mang lại tâm hồn dịu dàng, giàu trí tưởng tượng, nhạy cảm nghệ thuật, yêu hoà bình và luôn quan tâm tới cảm xúc của người khác.', 'AI', 4, '§5', 26, 28, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(326, 'VED-JOH-DINH-MENH-2', 'Số định mệnh 2 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '2', '{"chi_so": "JOHARI_DINH_MENH", "bang": 2}', 'Theo Johari (§5, tr.PDF 29–30), Số định mệnh 2 mang lại sức hút xã hội và trực giác tinh tế, nhưng kèm theo thử thách cần lưu ý là tâm trạng dễ dao động theo hoàn cảnh và đôi khi công sức bỏ ra cần nhiều thời gian mới được ghi nhận xứng đáng.', 'AI', 4, '§5', 29, 30, 'THAP', 'DUNG', 'Đã diễn đạt lại nhận định ''không tốt'' của Johari thành ''thử thách cần lưu ý'' theo Mục 9.1 (Xung đột #10).', 2, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(327, 'VED-JOH-KHUYEN-CAO-NGHE-2', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 2 (Johari)', 'QUY_TAC', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Johari (§5, tr.PDF 28, 30) khuyên bạn rèn luyện tính quyết đoán, không để cảm xúc lên xuống theo chu kỳ trăng và hoàn tất công việc đã bắt đầu. Nghề nghiệp phù hợp là nghệ thuật, tâm lý, điều dưỡng, du lịch, ngoại giao và dịch vụ cộng đồng.', 'DI_THE_NAO', 4, '§5', 28, 30, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(328, 'VED-JOH-NGHE-DINH-MENH-2', 'Định hướng nghề nghiệp theo Số định mệnh 2 (Johari)', 'QUY_TAC', 21, 2, '2', '{"chi_so": "JOHARI_DINH_MENH", "bang": 2}', 'Theo Johari (§5, tr.PDF 29), với Số định mệnh 2 (Mặt Trăng (Chandra)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: nghệ thuật, tâm lý, điều dưỡng, du lịch, ngoại giao và dịch vụ cộng đồng.', 'DI_THE_NAO', 4, '§5', 29, 31, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(329, 'VED-JOH-THOI-DIEM-2', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 2 (Johari)', 'QUY_TAC', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Theo Johari (§5, tr.PDF 34), khoảng thời gian năng lượng Mặt Trăng mạnh trong năm là từ 20/6 đến 27/7; bạn cần giữ tinh thần ổn định trong những tháng mùa đông thiếu ánh sáng.', 'GAP_GI', 4, '§5', 34, 35, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(330, 'VED-JOH-VAN-HOA-2', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 2 (Johari)', 'QUY_TAC', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Theo Johari (§5, tr.PDF 33–34), gợi ý văn hoá Vệ Đà cho số 2: màu sắc hài hoà là trắng, kem, xanh lá nhạt; ngày trong tuần thuận lợi là Thứ Hai, Chủ nhật và Thứ Sáu; các ngày hợp là 2, 11, 20, 29.', 'DI_THE_NAO', 4, '§5', 33, 35, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(331, 'VED-JOH-QUAN-HE-2', 'Quan hệ tương hợp / đối nghịch của Số 2 (Johari)', 'QUY_TAC', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Theo Johari (§5, tr.PDF 31), số 2 tương hợp với các số 1, 2, 3, 5; trung tính với 6, 8, 9; và không hợp với số 4, 7.', 'DI_THE_NAO', 4, '§5', 31, 32, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(332, 'VED-JOH-DA-QUY-NHIN-AN-2', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 2 (Johari)', 'MO_TA', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Theo Johari (§5, tr.PDF 32–33), đá quý truyền thống gắn với số 2 là ngọc trai (Pearl) hoặc đá mặt trăng (Moonstone), cùng nghi thức nhịn ăn ngày Thứ Hai.', 'DI_THE_NAO', 4, '§5', 32, 34, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(333, 'VED-JOH-AYURVEDA-BENH-2', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 2 (Johari)', 'MO_TA', 20, 2, '2', '{"chi_so": "JOHARI_TAM_HON", "bang": 2}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 2 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§5).', 'NEN_TANG', 4, '§5', 30, 31, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(334, 'VED-JOH-TAM-HON-3', 'Số tâm hồn 3 — Hành tinh Mộc tinh (Guru / Jupiter) (Johari)', 'QUY_TAC', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Theo Harish Johari (§6, tr.PDF 36–38), Số tâm hồn 3 (chủ quản bởi Mộc tinh - người thầy tâm linh) biểu thị trí tuệ học thuật, tính kỷ luật, lòng tự trọng cao, tinh thần lạc quan và khả năng cố vấn.', 'AI', 4, '§6', 36, 38, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(335, 'VED-JOH-DINH-MENH-3', 'Số định mệnh 3 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '3', '{"chi_so": "JOHARI_DINH_MENH", "bang": 3}', 'Theo Johari (§6, tr.PDF 39–40), Số định mệnh 3 mang lại uy tín tri thức và cơ hội thăng tiến rộng mở, nhưng có thử thách cần lưu ý là bạn dễ ôm đồm quá nhiều trách nhiệm cùng lúc dẫn tới căng thẳng và làm việc quá tải.', 'AI', 4, '§6', 39, 40, 'THAP', 'DUNG', 'Đã diễn đạt lại nhận định ''không tốt'' của Johari thành ''thử thách cần lưu ý'' theo Mục 9.1 (Xung đột #10).', 2, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(336, 'VED-JOH-KHUYEN-CAO-NGHE-3', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 3 (Johari)', 'QUY_TAC', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Johari (§6, tr.PDF 38, 40) khuyên bạn kiểm soát cái tôi học thức, tránh tiêu xài phô trương và học cách phân quyền. Nghề nghiệp phù hợp là giảng dạy, nghiên cứu khoa học, thẩm phán, luật sư, cố vấn tài chính và quản trị.', 'DI_THE_NAO', 4, '§6', 38, 40, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(337, 'VED-JOH-NGHE-DINH-MENH-3', 'Định hướng nghề nghiệp theo Số định mệnh 3 (Johari)', 'QUY_TAC', 21, 2, '3', '{"chi_so": "JOHARI_DINH_MENH", "bang": 3}', 'Theo Johari (§6, tr.PDF 39), với Số định mệnh 3 (Mộc tinh (Guru / Jupiter)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: giảng dạy, nghiên cứu khoa học, thẩm phán, luật sư, cố vấn tài chính và quản trị.', 'DI_THE_NAO', 4, '§6', 39, 41, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(338, 'VED-JOH-THOI-DIEM-3', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 3 (Johari)', 'QUY_TAC', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Theo Johari (§6, tr.PDF 43), khoảng thời gian vượng năng lượng của số 3 trong năm là từ 19/2 đến 20/3 và từ 21/11 đến 20/12.', 'GAP_GI', 4, '§6', 43, 44, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(339, 'VED-JOH-VAN-HOA-3', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 3 (Johari)', 'QUY_TAC', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Theo Johari (§6, tr.PDF 42–43), gợi ý văn hoá Vệ Đà cho số 3: màu sắc hài hoà là vàng nghệ, hồng ánh tím; ngày trong tuần thuận lợi là Thứ Năm, Thứ Hai và Thứ Ba; các ngày hợp là 3, 12, 21, 30.', 'DI_THE_NAO', 4, '§6', 42, 44, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(340, 'VED-JOH-QUAN-HE-3', 'Quan hệ tương hợp / đối nghịch của Số 3 (Johari)', 'QUY_TAC', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Theo Johari (§6, tr.PDF 40–41), số 3 tương hợp với các số 1, 2, 3, 6, 9; trung tính với 4, 7, 8; và đối nghịch với số 5.', 'DI_THE_NAO', 4, '§6', 41, 42, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(341, 'VED-JOH-DA-QUY-NHIN-AN-3', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 3 (Johari)', 'MO_TA', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Theo Johari (§6, tr.PDF 41–42), đá quý truyền thống gắn với số 3 là Hoàng ngọc (Yellow Sapphire / Topaz) và nhịn ăn ngày Thứ Năm.', 'DI_THE_NAO', 4, '§6', 41, 43, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(342, 'VED-JOH-AYURVEDA-BENH-3', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 3 (Johari)', 'MO_TA', 20, 2, '3', '{"chi_so": "JOHARI_TAM_HON", "bang": 3}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 3 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§6).', 'NEN_TANG', 4, '§6', 40, 41, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(343, 'VED-JOH-TAM-HON-4', 'Số tâm hồn 4 — Hành tinh Rahu (La Hầu - Bắc giao điểm) (Johari)', 'QUY_TAC', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Theo Harish Johari (§7, tr.PDF 45–47), Số tâm hồn 4 (chủ quản bởi Rahu) cho thấy cá tính độc đáo, dám thách thức khuôn mẫu cũ, kiên cường trước nghịch cảnh và luôn đứng về phía người yếu thế.', 'AI', 4, '§7', 45, 47, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(344, 'VED-JOH-DINH-MENH-4', 'Số định mệnh 4 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '4', '{"chi_so": "JOHARI_DINH_MENH", "bang": 4}', 'Theo Johari (§7, tr.PDF 48–49), Số định mệnh 4 thường mang đến những biến động bất ngờ trong công việc và cuộc sống; đây là thử thách cần lưu ý để bạn rèn luyện tính kiên trì, sự cẩn trọng tài chính và bản lĩnh ứng biến.', 'AI', 4, '§7', 48, 49, 'THAP', 'DUNG', 'Đã diễn đạt lại nhận định ''không tốt'' của Johari thành ''thử thách cần lưu ý'' theo Mục 9.1 (Xung đột #10).', 2, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(345, 'VED-JOH-KHUYEN-CAO-NGHE-4', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 4 (Johari)', 'QUY_TAC', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Johari (§7, tr.PDF 47, 49) khuyên bạn tránh tranh cãi gay gắt, giảm sự đa nghi và lập kế hoạch tài chính rõ ràng. Nghề nghiệp phù hợp là kỹ sư, công nghệ thông tin, cải cách xã hội, nghiên cứu kỹ thuật và quản lý vận hành.', 'DI_THE_NAO', 4, '§7', 47, 49, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(346, 'VED-JOH-NGHE-DINH-MENH-4', 'Định hướng nghề nghiệp theo Số định mệnh 4 (Johari)', 'QUY_TAC', 21, 2, '4', '{"chi_so": "JOHARI_DINH_MENH", "bang": 4}', 'Theo Johari (§7, tr.PDF 48), với Số định mệnh 4 (Rahu (La Hầu - Bắc giao điểm)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: kỹ sư, công nghệ thông tin, cải cách xã hội, nghiên cứu kỹ thuật và quản lý vận hành.', 'DI_THE_NAO', 4, '§7', 48, 50, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(347, 'VED-JOH-THOI-DIEM-4', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 4 (Johari)', 'QUY_TAC', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Theo Johari (§7, tr.PDF 53), khoảng thời gian thuận lợi trong năm của số 4 là từ 21/3 đến 28/4 và từ 10/7 đến 20/8.', 'GAP_GI', 4, '§7', 53, 54, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(348, 'VED-JOH-VAN-HOA-4', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 4 (Johari)', 'QUY_TAC', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Theo Johari (§7, tr.PDF 52–53), gợi ý văn hoá Vệ Đà cho số 4: màu sắc hài hoà là xanh dương, xám bạc, khaki; ngày trong tuần thuận lợi là Thứ Bảy, Chủ nhật và Thứ Hai; các ngày hợp là 4, 13, 22, 31.', 'DI_THE_NAO', 4, '§7', 52, 54, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(349, 'VED-JOH-QUAN-HE-4', 'Quan hệ tương hợp / đối nghịch của Số 4 (Johari)', 'QUY_TAC', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Theo Johari (§7, tr.PDF 50), số 4 tương hợp với các số 1, 4, 5, 6, 7, 8; trung tính với 3, 9; và không hợp với số 2.', 'DI_THE_NAO', 4, '§7', 50, 51, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(350, 'VED-JOH-DA-QUY-NHIN-AN-4', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 4 (Johari)', 'MO_TA', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Theo Johari (§7, tr.PDF 51–52), đá quý truyền thống của Rahu là đá Hessonite (Gomed) và nhịn ăn ngày Thứ Bảy.', 'DI_THE_NAO', 4, '§7', 51, 53, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(351, 'VED-JOH-AYURVEDA-BENH-4', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 4 (Johari)', 'MO_TA', 20, 2, '4', '{"chi_so": "JOHARI_TAM_HON", "bang": 4}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 4 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§7).', 'NEN_TANG', 4, '§7', 49, 50, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(352, 'VED-JOH-TAM-HON-5', 'Số tâm hồn 5 — Hành tinh Thuỷ tinh (Budha / Mercury) (Johari)', 'QUY_TAC', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Theo Harish Johari (§8, tr.PDF 55–57), Số tâm hồn 5 (chủ quản bởi Thuỷ tinh) mang lại trí thông minh sắc sảo, phản xạ nhanh nhạy, tài ăn nói thuyết phục, tính cách trẻ trung và khả năng thích ứng linh hoạt.', 'AI', 4, '§8', 55, 57, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(353, 'VED-JOH-DINH-MENH-5', 'Số định mệnh 5 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '5', '{"chi_so": "JOHARI_DINH_MENH", "bang": 5}', 'Theo Johari (§8, tr.PDF 58), Số định mệnh 5 rất thuận lợi cho con đường thương mại, truyền thông và tài chính, giúp bạn dễ dàng nắm bắt cơ hội và nhận được sự hỗ trợ từ nhiều mối quan hệ.', 'AI', 4, '§8', 58, 59, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(354, 'VED-JOH-KHUYEN-CAO-NGHE-5', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 5 (Johari)', 'QUY_TAC', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Johari (§8, tr.PDF 57–58) khuyên bạn tránh để tâm trí hoạt động quá mức gây mất ngủ, giữ chữ tín và không quyết định vội vàng. Nghề nghiệp phù hợp là thương mại, ngân hàng, báo chí, truyền thông, ngoại giao và kinh doanh quốc tế.', 'DI_THE_NAO', 4, '§8', 57, 59, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(355, 'VED-JOH-NGHE-DINH-MENH-5', 'Định hướng nghề nghiệp theo Số định mệnh 5 (Johari)', 'QUY_TAC', 21, 2, '5', '{"chi_so": "JOHARI_DINH_MENH", "bang": 5}', 'Theo Johari (§8, tr.PDF 58), với Số định mệnh 5 (Thuỷ tinh (Budha / Mercury)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: thương mại, ngân hàng, báo chí, truyền thông, ngoại giao và kinh doanh quốc tế.', 'DI_THE_NAO', 4, '§8', 58, 60, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(356, 'VED-JOH-THOI-DIEM-5', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 5 (Johari)', 'QUY_TAC', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Theo Johari (§8, tr.PDF 61), giai đoạn mạnh mẽ trong năm của số 5 là từ 21/5 đến 20/6 và từ 21/8 đến 20/9.', 'GAP_GI', 4, '§8', 61, 62, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(357, 'VED-JOH-VAN-HOA-5', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 5 (Johari)', 'QUY_TAC', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Theo Johari (§8, tr.PDF 60–61), gợi ý văn hoá Vệ Đà cho số 5: màu sắc hài hoà là xanh lá cây, trắng và các gam màu sáng; ngày trong tuần thuận lợi là Thứ Tư và Thứ Sáu; các ngày hợp là 5, 14, 23.', 'DI_THE_NAO', 4, '§8', 60, 62, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(358, 'VED-JOH-QUAN-HE-5', 'Quan hệ tương hợp / đối nghịch của Số 5 (Johari)', 'QUY_TAC', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Theo Johari (§8, tr.PDF 59), số 5 tương hợp với các số 1, 4, 5, 6, 7, 8; trung tính với 3, 9; và không hợp với số 2.', 'DI_THE_NAO', 4, '§8', 60, 61, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(359, 'VED-JOH-DA-QUY-NHIN-AN-5', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 5 (Johari)', 'MO_TA', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Theo Johari (§8, tr.PDF 60), đá quý truyền thống của Thuỷ tinh là Ngọc lục bảo (Emerald) và nhịn ăn ngày Thứ Tư.', 'DI_THE_NAO', 4, '§8', 59, 61, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(360, 'VED-JOH-AYURVEDA-BENH-5', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 5 (Johari)', 'MO_TA', 20, 2, '5', '{"chi_so": "JOHARI_TAM_HON", "bang": 5}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 5 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§8).', 'NEN_TANG', 4, '§8', 59, 60, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(361, 'VED-JOH-TAM-HON-6', 'Số tâm hồn 6 — Hành tinh Kim tinh (Shukra / Venus) (Johari)', 'QUY_TAC', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Theo Harish Johari (§9, tr.PDF 63–65), Số tâm hồn 6 (chủ quản bởi Kim tinh) biểu thị tâm hồn yêu cái đẹp, lịch thiệp, giàu sức hút, trọng tình cảm gia đình và có năng khiếu nghệ thuật tinh tế.', 'AI', 4, '§9', 63, 65, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(362, 'VED-JOH-DINH-MENH-6', 'Số định mệnh 6 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '6', '{"chi_so": "JOHARI_DINH_MENH", "bang": 6}', 'Theo Johari (§9, tr.PDF 66–67), Số định mệnh 6 mang lại nhiều bạn bè quý mến và môi trường sống tiện nghi, nhưng có thử thách cần lưu ý là dễ bị cuốn vào việc lo toan tình cảm cho người khác hoặc chiều chuộng cảm xúc cá nhân quá mức.', 'AI', 4, '§9', 66, 67, 'THAP', 'DUNG', 'Đã diễn đạt lại nhận định ''không tốt'' của Johari thành ''thử thách cần lưu ý'' theo Mục 9.1 (Xung đột #10).', 2, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(363, 'VED-JOH-KHUYEN-CAO-NGHE-6', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 6 (Johari)', 'QUY_TAC', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Johari (§9, tr.PDF 65, 67) khuyên bạn rèn luyện tính kỷ luật, tránh sự trì trệ và giữ cân bằng giữa cảm xúc với lý trí. Nghề nghiệp phù hợp là thiết kế thời trang, kiến trúc, âm nhạc, điện ảnh, khách sạn - du lịch và chăm sóc sắc đẹp.', 'DI_THE_NAO', 4, '§9', 65, 67, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(364, 'VED-JOH-NGHE-DINH-MENH-6', 'Định hướng nghề nghiệp theo Số định mệnh 6 (Johari)', 'QUY_TAC', 21, 2, '6', '{"chi_so": "JOHARI_DINH_MENH", "bang": 6}', 'Theo Johari (§9, tr.PDF 66), với Số định mệnh 6 (Kim tinh (Shukra / Venus)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: thiết kế thời trang, kiến trúc, âm nhạc, điện ảnh, khách sạn - du lịch và chăm sóc sắc đẹp.', 'DI_THE_NAO', 4, '§9', 66, 68, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(365, 'VED-JOH-THOI-DIEM-6', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 6 (Johari)', 'QUY_TAC', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Theo Johari (§9, tr.PDF 69), thời điểm năng lượng Kim tinh vượng nhất trong năm là từ 20/4 đến 18/5 và từ 21/9 đến 19/10.', 'GAP_GI', 4, '§9', 69, 70, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(366, 'VED-JOH-VAN-HOA-6', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 6 (Johari)', 'QUY_TAC', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Theo Johari (§9, tr.PDF 68–69), gợi ý văn hoá Vệ Đà cho số 6: màu sắc hài hoà là trắng, xanh da trời, hồng phấn; ngày trong tuần thuận lợi là Thứ Sáu, Thứ Ba và Thứ Năm; các ngày hợp là 6, 15, 24.', 'DI_THE_NAO', 4, '§9', 68, 70, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(367, 'VED-JOH-QUAN-HE-6', 'Quan hệ tương hợp / đối nghịch của Số 6 (Johari)', 'QUY_TAC', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Theo Johari (§1 tr.PDF 6 & §9 tr.PDF 67), số 6 là ''bạn chung'' (Universal Friend), tương hợp với hầu hết các số 1, 3, 4, 5, 6, 7, 8, 9 và trung tính với số 2.', 'DI_THE_NAO', 4, '§9', 68, 69, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(368, 'VED-JOH-DA-QUY-NHIN-AN-6', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 6 (Johari)', 'MO_TA', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Theo Johari (§9, tr.PDF 68), đá quý truyền thống của Kim tinh là Kim cương (Diamond) hoặc đá Tourmaline trắng và nhịn ăn ngày Thứ Sáu.', 'DI_THE_NAO', 4, '§9', 67, 69, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(369, 'VED-JOH-AYURVEDA-BENH-6', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 6 (Johari)', 'MO_TA', 20, 2, '6', '{"chi_so": "JOHARI_TAM_HON", "bang": 6}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 6 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§9).', 'NEN_TANG', 4, '§9', 67, 68, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(370, 'VED-JOH-TAM-HON-7', 'Số tâm hồn 7 — Hành tinh Ketu (Kế Đô - Nam giao điểm) (Johari)', 'QUY_TAC', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Theo Harish Johari (§10, tr.PDF 71–73), Số tâm hồn 7 (chủ quản bởi Ketu) mang lại trực giác tâm linh sâu sắc, óc sáng tạo độc lập, yêu thích triết học và khám phá những miền tri thức mới.', 'AI', 4, '§10', 71, 73, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(371, 'VED-JOH-DINH-MENH-7', 'Số định mệnh 7 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '7', '{"chi_so": "JOHARI_DINH_MENH", "bang": 7}', 'Theo Johari (§10, tr.PDF 74–75), Số định mệnh 7 là con số rất tốt cho sự phát triển trí tuệ, trực giác và uy tín tinh thần (đây cũng là Số định mệnh của chính tác giả Harish Johari), giúp bạn trở thành người dẫn đường về tri thức và tâm thức.', 'AI', 4, '§10', 74, 75, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(372, 'VED-JOH-KHUYEN-CAO-NGHE-7', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 7 (Johari)', 'QUY_TAC', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Johari (§10, tr.PDF 73, 75) khuyên bạn kiên trì theo đuổi mục tiêu đến cùng, tránh tâm lý do dự hoặc tách biệt quá mức khỏi thực tế. Nghề nghiệp phù hợp là nghiên cứu khoa học, triết học, giảng dạy, viết sách, y học tự nhiên và tư vấn.', 'DI_THE_NAO', 4, '§10', 73, 75, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(373, 'VED-JOH-NGHE-DINH-MENH-7', 'Định hướng nghề nghiệp theo Số định mệnh 7 (Johari)', 'QUY_TAC', 21, 2, '7', '{"chi_so": "JOHARI_DINH_MENH", "bang": 7}', 'Theo Johari (§10, tr.PDF 74), với Số định mệnh 7 (Ketu (Kế Đô - Nam giao điểm)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: nghiên cứu khoa học, triết học, giảng dạy, viết sách, y học tự nhiên và tư vấn.', 'DI_THE_NAO', 4, '§10', 74, 76, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(374, 'VED-JOH-THOI-DIEM-7', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 7 (Johari)', 'QUY_TAC', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Theo Johari (§10, tr.PDF 78), khoảng thời gian thuận lợi trong năm của số 7 là từ 21/6 đến 20/7.', 'GAP_GI', 4, '§10', 78, 79, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(375, 'VED-JOH-VAN-HOA-7', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 7 (Johari)', 'QUY_TAC', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Theo Johari (§10, tr.PDF 77–78), gợi ý văn hoá Vệ Đà cho số 7: màu sắc hài hoà là trắng, xanh lá nhạt, vàng nhạt và hoạ tiết nhiều màu; ngày trong tuần thuận lợi là Chủ nhật, Thứ Hai và Thứ Tư; các ngày hợp là 7, 16, 25.', 'DI_THE_NAO', 4, '§10', 77, 79, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(376, 'VED-JOH-QUAN-HE-7', 'Quan hệ tương hợp / đối nghịch của Số 7 (Johari)', 'QUY_TAC', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Theo Johari (§10, tr.PDF 75–76), số 7 tương hợp với các số 1, 4, 5, 6, 7; trung tính với 3, 8, 9; và không hợp với số 2.', 'DI_THE_NAO', 4, '§10', 76, 77, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(377, 'VED-JOH-DA-QUY-NHIN-AN-7', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 7 (Johari)', 'MO_TA', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Theo Johari (§10, tr.PDF 76–77), đá quý truyền thống của Ketu là đá Mắt mèo (Cat''s Eye / Lehsuniya).', 'DI_THE_NAO', 4, '§10', 76, 78, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(378, 'VED-JOH-AYURVEDA-BENH-7', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 7 (Johari)', 'MO_TA', 20, 2, '7', '{"chi_so": "JOHARI_TAM_HON", "bang": 7}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 7 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§10).', 'NEN_TANG', 4, '§10', 75, 76, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(379, 'VED-JOH-TAM-HON-8', 'Số tâm hồn 8 — Hành tinh Thổ tinh (Shani / Saturn) (Johari)', 'QUY_TAC', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Theo Harish Johari (§11, tr.PDF 80–82), Số tâm hồn 8 (chủ quản bởi Thổ tinh) biểu thị nghị lực bền bỉ, tính thực tế, sự kiên nhẫn vượt khó và tinh thần trách nhiệm cao với công việc.', 'AI', 4, '§11', 80, 82, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(380, 'VED-JOH-DINH-MENH-8', 'Số định mệnh 8 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '8', '{"chi_so": "JOHARI_DINH_MENH", "bang": 8}', 'Theo Johari (§11, tr.PDF 83–84), Số định mệnh 8 đặt ra thử thách cần lưu ý là thành công thường đến muộn sau nhiều nỗ lực gian nan; khi bạn rèn luyện được sự kiên định và kỷ luật, Thổ tinh lại trao cho bạn thành tựu bền vững cả về vật chất lẫn chiều sâu trí tuệ.', 'AI', 4, '§11', 83, 84, 'THAP', 'DUNG', 'Đã diễn đạt lại nhận định ''không tốt'' của Johari thành ''thử thách cần lưu ý'' theo Mục 9.1 (Xung đột #10).', 2, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(381, 'VED-JOH-KHUYEN-CAO-NGHE-8', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 8 (Johari)', 'QUY_TAC', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Johari (§11, tr.PDF 82, 84) khuyên bạn giữ thái độ lạc quan, tránh cảm giác cô đơn bi quan và tin tưởng cộng sự. Nghề nghiệp phù hợp là công nghiệp kỹ thuật, xây dựng, khai khoáng, quản lý tài chính, luật pháp và hoạt động xã hội.', 'DI_THE_NAO', 4, '§11', 82, 84, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(382, 'VED-JOH-NGHE-DINH-MENH-8', 'Định hướng nghề nghiệp theo Số định mệnh 8 (Johari)', 'QUY_TAC', 21, 2, '8', '{"chi_so": "JOHARI_DINH_MENH", "bang": 8}', 'Theo Johari (§11, tr.PDF 83), với Số định mệnh 8 (Thổ tinh (Shani / Saturn)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: công nghiệp kỹ thuật, xây dựng, khai khoáng, quản lý tài chính, luật pháp và hoạt động xã hội.', 'DI_THE_NAO', 4, '§11', 83, 85, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(383, 'VED-JOH-THOI-DIEM-8', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 8 (Johari)', 'QUY_TAC', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Theo Johari (§11, tr.PDF 87), giai đoạn tuổi phát triển mạnh của số 8 là sau tuổi 35–40; thời điểm vượng trong năm là từ 20/9 đến 25/10 và từ 20/1 đến 20/2.', 'GAP_GI', 4, '§11', 87, 88, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(384, 'VED-JOH-VAN-HOA-8', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 8 (Johari)', 'QUY_TAC', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Theo Johari (§11, tr.PDF 86–87), gợi ý văn hoá Vệ Đà cho số 8: màu sắc hài hoà là xanh đen, đen, tím sẫm; ngày trong tuần thuận lợi là Thứ Bảy, Thứ Sáu và Thứ Tư; các ngày hợp là 8, 17, 26.', 'DI_THE_NAO', 4, '§11', 86, 88, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(385, 'VED-JOH-QUAN-HE-8', 'Quan hệ tương hợp / đối nghịch của Số 8 (Johari)', 'QUY_TAC', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Theo Johari (§11, tr.PDF 84–85), số 8 tương hợp với các số 4, 5, 6, 7, 8; trung tính với 3, 9; và đối nghịch với số 1, 2.', 'DI_THE_NAO', 4, '§11', 85, 86, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(386, 'VED-JOH-DA-QUY-NHIN-AN-8', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 8 (Johari)', 'MO_TA', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Theo Johari (§11, tr.PDF 85–86), đá quý truyền thống của Thổ tinh là Lam ngọc (Blue Sapphire / Neelam) và nhịn ăn ngày Thứ Bảy.', 'DI_THE_NAO', 4, '§11', 85, 87, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(387, 'VED-JOH-AYURVEDA-BENH-8', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 8 (Johari)', 'MO_TA', 20, 2, '8', '{"chi_so": "JOHARI_TAM_HON", "bang": 8}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 8 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§11).', 'NEN_TANG', 4, '§11', 84, 85, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(388, 'VED-JOH-TAM-HON-9', 'Số tâm hồn 9 — Hành tinh Hoả tinh (Mangala / Mars) (Johari)', 'QUY_TAC', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Theo Harish Johari (§12, tr.PDF 89–91), Số tâm hồn 9 (chủ quản bởi Hoả tinh) mang nguồn năng lượng mạnh mẽ, lòng dũng cảm, tinh thần nghĩa hiệp, dám đương đầu thử thách và hướng tới hoàn thiện.', 'AI', 4, '§12', 89, 91, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(389, 'VED-JOH-DINH-MENH-9', 'Số định mệnh 9 theo Vệ Đà (Johari)', 'QUY_TAC', 21, 2, '9', '{"chi_so": "JOHARI_DINH_MENH", "bang": 9}', 'Theo Johari (§12, tr.PDF 92–93), Số định mệnh 9 thuận lợi cho việc xây dựng vị thế lãnh đạo, quản trị và hoàn thành những sứ mệnh lớn khi bạn biết kiểm soát năng lượng nhiệt huyết.', 'AI', 4, '§12', 92, 93, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(390, 'VED-JOH-KHUYEN-CAO-NGHE-9', 'Khuyến cáo rèn luyện & Nghề nghiệp cho Số 9 (Johari)', 'QUY_TAC', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Johari (§12, tr.PDF 91, 93) khuyên bạn kiềm chế tính nóng nảy, tránh tranh luận gay gắt và rèn sự điềm tĩnh trong gia đình. Nghề nghiệp phù hợp là quản lý điều hành, kỹ thuật cơ khí, thể thao, y tế ngoại khoa và công tác cộng đồng.', 'DI_THE_NAO', 4, '§12', 91, 93, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(391, 'VED-JOH-NGHE-DINH-MENH-9', 'Định hướng nghề nghiệp theo Số định mệnh 9 (Johari)', 'QUY_TAC', 21, 2, '9', '{"chi_so": "JOHARI_DINH_MENH", "bang": 9}', 'Theo Johari (§12, tr.PDF 92), với Số định mệnh 9 (Hoả tinh (Mangala / Mars)), sau tuổi 35 môi trường xã hội và nghề nghiệp của bạn thuận lợi khi hướng tới: quản lý điều hành, kỹ thuật cơ khí, thể thao, y tế ngoại khoa và công tác cộng đồng.', 'DI_THE_NAO', 4, '§12', 92, 94, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(392, 'VED-JOH-THOI-DIEM-9', 'Giai đoạn tuổi & Khoảng thời gian mạnh trong năm của Số 9 (Johari)', 'QUY_TAC', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Theo Johari (§12, tr.PDF 96), thời điểm năng lượng Hoả tinh mạnh nhất trong năm là từ 21/3 đến 26/4 và từ 21/10 đến 27/11.', 'GAP_GI', 4, '§12', 97, 98, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(393, 'VED-JOH-VAN-HOA-9', 'Màu sắc, Thứ và Ngày hợp theo truyền thống Vệ Đà cho Số 9 (Johari)', 'QUY_TAC', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Theo Johari (§12, tr.PDF 95–96), gợi ý văn hoá Vệ Đà cho số 9: màu sắc hài hoà là các sắc độ đỏ, hồng đậm; ngày trong tuần thuận lợi là Thứ Ba, Thứ Năm và Thứ Sáu; các ngày hợp là 9, 18, 27.', 'DI_THE_NAO', 4, '§12', 96, 98, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc và ngày/thứ tốt thuộc truyền thống văn hoá Vệ Đà, gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(394, 'VED-JOH-QUAN-HE-9', 'Quan hệ tương hợp / đối nghịch của Số 9 (Johari)', 'QUY_TAC', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Theo Johari (§12, tr.PDF 93–94), số 9 tương hợp với các số 1, 2, 3, 6, 9; trung tính với 4, 7, 8; và không hợp với số 5.', 'DI_THE_NAO', 4, '§12', 94, 95, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(395, 'VED-JOH-DA-QUY-NHIN-AN-9', 'Đá quý, Thần chú (Mantra) & Nghi thức nhịn ăn cho Số 9 (Johari)', 'MO_TA', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Theo Johari (§12, tr.PDF 94–95), đá quý truyền thống của Hoả tinh là San hô đỏ (Red Coral) và nhịn ăn ngày Thứ Ba.', 'DI_THE_NAO', 4, '§12', 95, 97, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Đá quý, thần chú và nhịn ăn gắn nhãn THAN_TRONG, chỉ lưu trong Kho.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(396, 'VED-JOH-AYURVEDA-BENH-9', 'Thể tạng Ayurveda (Dosha) & Lưu ý sức khoẻ của Số 9 (Johari)', 'MO_TA', 20, 2, '9', '{"chi_so": "JOHARI_TAM_HON", "bang": 9}', 'Nội dung mô tả thể tạng Ayurveda (Vata, Pitta, Kapha) và các chứng bệnh liên quan đến số 9 trong mục ''Balancing the Interior and Exterior Environments'' của Johari (§12).', 'NEN_TANG', 4, '§12', 93, 94, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Nội dung về sức khoẻ, bệnh tật, thể tạng Ayurveda gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(397, 'VED-JOH-NGAY-13-TAM-HON-4', 'Số tâm hồn 4 sinh ngày 13 (Johari §13)', 'QUY_TAC', 23, 2, '4:13', '{"chi_so": "JOHARI_TAM_HON", "bang": 4, "ngay_sinh_trong": [13]}', 'Theo Harish Johari (§13, tr.PDF 101), người có Số tâm hồn 4 sinh vào ngày 13 kết hợp năng lượng lãnh đạo của Mặt Trời (1) và trí tuệ của Mộc tinh (3) tạo thành Rahu (4): bạn có tư duy thực tế sắc bén và thường trải qua những thay đổi đột ngột thúc đẩy sự trưởng thành.', 'AI', 4, '§13', 101, 101, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
(398, 'VED-JOH-SO-KEP-10', 'Số kép ngày sinh 10 (Johari §13)', 'QUY_TAC', 23, 2, '10', '{"chi_so": "JOHARI_SO_KEP", "bang": 10}', 'Theo Harish Johari (§13, tr.PDF 100), sinh ngày 10 kết hợp ảnh hưởng của chữ số đứng trước (1 - Mặt Trời, đóng vai trò chủ đạo) và chữ số đứng sau (0 - Số 0 (Không tính)), hội tụ về Số tâm hồn 1.', 'AI', 4, '§13', 100, 100, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF'),
